package com.knowflow.controller;
import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"knowflow.product.adaptive-learning.enabled=true","knowflow.product.interview-learning.enabled=true","knowflow.product.private-quiz.enabled=true","knowflow.product.tutor.enabled=true","knowflow.product.tutor-coaching.enabled=true","server.address=127.0.0.1"})
class ProductSmartPlanHttpTest extends ProductFeedbackHttpTest {
 @Autowired com.knowflow.learning.actions.LearningWriteGuard guard;@Autowired com.knowflow.service.TaskService tasks;@Autowired com.knowflow.mapper.TaskMapper mapper;
 @Test void budgetLocksDeferralReplayAndOwnershipUseOriginalTasks()throws Exception{
  var today=LocalDate.now(ZoneId.of("Asia/Shanghai"));var ids=new ArrayList<Long>();for(int i=0;i<3;i++){var dto=new com.knowflow.dto.TaskDTO();dto.setTitle("合成任务"+i);dto.setScheduledDate(today);dto.setSortOrder(i);ids.add(tasks.createTask(owner,dto));}
  String root="/api/learning/action-plans/smart";var rows=call("GET",root+"/tasks",null,owner,200);var first=rows.get(0);call("POST",root+"/tasks/"+ids.get(0)+"/settings",Map.of("revision",first.path("revision").asText(),"locked",true,"estimatedMinutes",30),owner,200);String frozen=json.writeValueAsString(mapper.selectById(ids.get(0)));
  call("POST",root+"/preview",Map.of("availableMinutes",20),owner,409);call("POST","/api/learning/action-plans/daily/changes",Map.of("availableMinutes",20),owner,409);var draft=call("POST",root+"/preview",Map.of("availableMinutes",45),owner,200);assertEquals(2,draft.path("tasks").size());assertEquals(15,draft.path("tasks").get(1).path("estimatedMinutes").asInt());assertEquals("DEFER",draft.path("changes").get(2).path("kind").asText());assertEquals(today,mapper.selectById(ids.get(2)).getScheduledDate());
  var edited=new ArrayList<Map<String,Object>>();for(var item:draft.path("tasks"))edited.add(Map.of("key",item.path("key").asText(),"title",item.path("title").asText(),"estimatedMinutes",item.path("estimatedMinutes").asInt(),"priority",item.path("priority").asText()));var confirmation=Map.of("version",draft.path("version").asInt(),"confirmationToken",draft.path("confirmationToken").asText(),"idempotencyKey",UUID.randomUUID().toString(),"tasks",edited);String id=draft.path("planId").asText();call("POST",root+"/"+id+"/confirm",confirmation,owner,200);call("POST",root+"/"+id+"/confirm",confirmation,owner,200);assertEquals(frozen,json.writeValueAsString(mapper.selectById(ids.get(0)))) ;assertEquals(today.plusDays(1),mapper.selectById(ids.get(2)).getScheduledDate());assertEquals(3,call("GET",root+"/tasks",null,owner,200).size()+1);assertEquals("CONFIRMED",call("GET",root+"/history",null,owner,200).get(0).path("state").asText());for(long other:new long[]{owner+1,owner+2})call("GET",root+"/"+id,null,other,404);call("GET",root+"/"+id,null,0,401);
  var registeredDto=new com.knowflow.dto.TaskDTO();registeredDto.setTitle("原计划登记的工具任务");registeredDto.setScheduledDate(today.plusDays(2));long registered=tasks.createTask(owner,registeredDto);var original=mapper.selectById(registered);var item=new com.knowflow.learning.actions.PlanModels.Item("stable-tool-identity","原计划登记的工具任务","THEORY",30,"LOW","TOOL",null,null,null,"原登记","手动完成",null,null,null);original.setLearningMetadata(json.writeValueAsString(item));original.setLearningPlanRef("original-plan");mapper.updateById(original);guard.rememberTask(owner,today.plusDays(2),guard.identity(item),registered);
  String revision;try{revision=java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(json.writeValueAsString(mapper.selectById(registered)).getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(Exception e){throw new AssertionError(e);}call("POST",root+"/tasks/"+registered+"/settings",Map.of("revision",revision,"locked",true,"estimatedMinutes",30),owner,200);assertEquals("stable-tool-identity",json.readTree(mapper.selectById(registered).getLearningMetadata()).path("key").asText());assertDoesNotThrow(()->guard.completionRequirement(mapper.selectById(registered)));

 }
}
